'use strict';

const grep = require('./utils/grep');

function evaluateCompilerRules(compilerRules, compilerMessages) {
  return compilerRules.map(rule => {
    const matches = [];
    if (!rule.compilerPattern || compilerMessages.length === 0) {
      return { rule, matches };
    }

    for (const pattern of rule.compilerPattern) {
      let re;
      try { re = new RegExp(pattern); } catch { continue; }

      for (const msg of compilerMessages) {
        if (msg.severity !== 'Error' && msg.severity !== 'Warning') continue;
        if (!msg.file) continue;
        const text = msg.messageId || '';
        if (re.test(text) || re.test(msg.message)) {
          matches.push({
            file: msg.file,
            line: msg.line,
            lineEnd: msg.lineEnd,
            col: msg.col,
            colEnd: msg.colEnd,
            context: msg.message,
            source: 'compiler',
          });
        }
      }
    }

    return { rule, matches };
  });
}

function classifyFindings(ctx, ruleResults) {
  const compilerRan = ctx.analysis.compilerRan;
  const manualReviewRules = [];

  for (const { rule, matches } of ruleResults) {
    const coverage = determineCoverage(rule, matches.length, compilerRan);

    if (matches.length > 0) {
      ctx.analysis.findings.push({
        ruleId: rule.id,
        title: rule.title,
        scope: rule.scope || [],
        group: rule.group || null,
        groupTitle: rule.groupTitle || null,
        capireSection: rule.capireSection || null,
        guidance: rule.guidance || null,
        body: rule.body || null,
        capireAnchor: rule.capireAnchor || null,
        compilerDetects: rule.compilerDetects || false,
        patternsComplete: rule.patternsComplete || false,
        compatFlag: rule.compatFlag || null,
        orRecipe: rule.orRecipe || null,
        coverage,
        matches: grep.deduplicateMatches(matches),
      });
    } else if (coverage === 'unknown') {
      manualReviewRules.push({
        ruleId: rule.id,
        title: rule.title,
        body: rule.body || null,
      });
    }
  }

  ctx.analysis.manualReviewRules = manualReviewRules;
}

/**
 * Returns 'clean', 'complete', 'incomplete', or 'unknown'.
 */
function determineCoverage(rule, findingsCount, compilerRan) {
  if (rule.patternsComplete) {
    return findingsCount > 0 ? 'complete' : 'clean';
  }
  if (rule.compilerDetects && compilerRan) {
    return findingsCount > 0 ? 'complete' : 'clean';
  }
  return findingsCount > 0 ? 'incomplete' : 'unknown';
}

module.exports = {
  evaluateCompilerRules,
  classifyFindings,
  determineCoverage,
};
